1	package org.springframework.samples.petclinic.util;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives an owner's {@code identityKey} - the single value all duplicate detection is expressed
7	 * through. It is {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)},
8	 * where the telephone is the owner's stored E.164 form and the email is its stored lower-cased form.
9	 * Two owners are duplicates when, and only when, their whole identity keys are equal; because the
10	 * telephone is part of the key, household members with different telephones have different keys.
11	 */
12	public final class OwnerIdentity {
13	
14	    private OwnerIdentity() {
15	    }
16	
17	    /**
18	     * @param owner the owner whose identity key to derive.
19	     * @return the identity key {@code telephone|email|householdId}, with a missing email or
20	     *         householdId contributing an empty segment.
21	     */
22	    public static String key(Owner owner) {
23	        return segment(owner.getTelephone()) + "|" + segment(owner.getEmail()) + "|"
24	                + segment(owner.getHouseholdId());
25	    }
26	
27	    private static String segment(String value) {
28	        return value == null ? "" : value;
29	    }
30	}
