1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	import org.springframework.samples.petclinic.util.OwnerIdentity;
8	
9	/**
10	 * The single duplicate-detection step for the create-owner pipeline: it rejects a request whose
11	 * derived {@code identityKey} (normalizedTelephone|email|householdId) exactly equals an existing
12	 * owner's. This one check subsumes the former separate telephone, email and household checks.
13	 *
14	 * <p>Runs after {@link BuildOwner} and {@link AssignHousehold}, so the new owner's telephone and
15	 * email are normalized and its household id is finalized (including any back-fill of existing
16	 * members) - the key is therefore compared against every other owner's finalized key. Because the
17	 * telephone is part of the key, two household members with different telephones have different keys
18	 * and both are allowed; only an exact whole-key match is a duplicate. Throws
19	 * {@link DuplicateIdentityException} (handled as 409) on a collision.
20	 */
21	public class CheckOwnerIdentityUnique {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
24	            throws DuplicateIdentityException {
25	        String identityKey = OwnerIdentity.key(owner);
26	        for (Owner existing : ownerRepository.findAll()) {
27	            // The owner being created is not yet persisted, so findAll() returns only other owners.
28	            // A soft-deleted owner is ignored, so its key never blocks a new create.
29	            if (Boolean.TRUE.equals(existing.getDeleted())) {
30	                continue;
31	            }
32	            if (identityKey.equals(OwnerIdentity.key(existing))) {
33	                throw new DuplicateIdentityException(identityKey);
34	            }
35	        }
36	    }
37	}
