3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Stamps the deterministic {@code householdId} onto a newly built owner. The id is a pure function
8	 * of the owner's last name and postcode (see {@link OwnerHousehold#id}), so it is always assigned -
9	 * owners with the same last name and postcode converge on the same value automatically, with no
10	 * lookup or coordination. Runs after {@link BuildOwner}, so the built owner (with its normalized
11	 * fields) is available to stamp, and before the household-duplicate check and identity check, which
12	 * both key off the finalized id.
13	 */
14	public class AssignHousehold {
15	
16	    public void service(@Val Owner owner) {
17	        owner.setHouseholdId(OwnerHousehold.id(owner.getLastName(), owner.getPostcode()));
18	    }
19	}
