1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.regex.Pattern;
7	
8	/**
9	 * Shared household rules for the create-owner pipeline. The household identifier is now
10	 * <em>deterministic</em>: it is derived from the owner's last name and postcode alone, so any two
11	 * owners with the same (normalized) last name and the same postcode resolve to the same id without
12	 * coordination. Concretely the id is the first 12 hex characters of {@code SHA-256} over
13	 * {@code normalizedLastName + '|' + postcode}. Because the id is a pure function of those two
14	 * fields, sharing a household is no longer something a request opts into to create a link - it
15	 * happens automatically. The {@code sharesHousehold} flag now only bypasses the household-duplicate
16	 * block (see {@link CheckOwnerHouseholdUnique}).
17	 */
18	final class OwnerHousehold {
19	
20	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
21	
22	    private OwnerHousehold() {
23	    }
24	
25	    /** Canonical form of a last name for household keying: trimmed, whitespace-collapsed, lower-cased. */
26	    static String normalize(String value) {
27	        if (value == null) {
28	            return "";
29	        }
30	        return WHITESPACE.matcher(value.trim()).replaceAll(" ").toLowerCase();
31	    }
32	
33	    /**
34	     * Deterministic identifier for the household of the given last name and postcode: the first 12
35	     * hex characters of {@code SHA-256(normalizedLastName + '|' + postcode)}. A null postcode
36	     * contributes an empty segment, so owners with the same last name and no postcode still share.
37	     */
38	    static String id(String lastName, String postcode) {
39	        String key = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
40	        return sha256hex(key).substring(0, 12);
41	    }
42	
43	    private static String sha256hex(String value) {
44	        try {
45	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
46	            StringBuilder sb = new StringBuilder(digest.length * 2);
47	            for (byte b : digest) {
48	                sb.append(String.format("%02x", b));
49	            }
50	            return sb.toString();
51	        }
52	        catch (NoSuchAlgorithmException e) {
53	            throw new IllegalStateException("SHA-256 unavailable", e);
54	        }
55	    }
56	}
