1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Soft-match detection for the create-owner pipeline. By the time this step runs the owner is
10	 * already known not to be a hard duplicate (an exact {@code identityKey} match is rejected earlier
11	 * with 409 by {@link CheckOwnerIdentityUnique}), so this step never sees one. It instead flags a
12	 * weaker resemblance: an owner that shares an existing owner's {@code lastName} and {@code postcode}
13	 * but has a different {@code telephone}. Such an owner is still created, with
14	 * {@code possibleDuplicate} set true and {@code possibleDuplicateOf} set to the matching owner's id;
15	 * otherwise the flag is false and the id null.
16	 *
17	 * <p>A <em>declared</em> household member (the request set {@code sharesHousehold}) is never
18	 * flagged: sharing a last name and postcode is exactly what a declared member does, so it is an
19	 * announced household, not a suspected duplicate. The flag is left false for such owners.
20	 *
21	 * <p>Runs after the owner's fields are finalized and before {@link SaveOwner}, so the comparison is
22	 * against every already-persisted owner and the new owner (not yet saved) is excluded. When several
23	 * existing owners match, the one with the smallest id wins, so the result is deterministic.
24	 */
25	public class AssignPossibleDuplicate {
26	
27	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
28	        owner.setPossibleDuplicate(false);
29	        owner.setPossibleDuplicateOf(null);
30	
31	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
32	            return; // a declared household member is not a suspected duplicate
33	        }
34	
35	        String lastName = owner.getLastName();
36	        String postcode = owner.getPostcode();
37	        String telephone = owner.getTelephone();
38	        if (lastName == null || postcode == null || telephone == null) {
39	            return;
40	        }
41	
42	        Integer matchId = null;
43	        for (Owner existing : ownerRepository.findAll()) {
44	            if (Boolean.TRUE.equals(existing.getDeleted())) {
45	                continue; // a soft-deleted owner is not a duplicate to match against
46	            }
47	            if (lastName.equalsIgnoreCase(existing.getLastName())
48	                    && postcode.equals(existing.getPostcode())
49	                    && !telephone.equals(existing.getTelephone())
50	                    && existing.getId() != null
51	                    && (matchId == null || existing.getId() < matchId)) {
52	                matchId = existing.getId();
53	            }
54	        }
55	
56	        if (matchId != null) {
57	            owner.setPossibleDuplicate(true);
58	            owner.setPossibleDuplicateOf(matchId);
59	        }
60	    }
61	}
