1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Set;
4	import java.util.regex.Pattern;
5	
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerEmailException;
8	
9	/**
10	 * Shared email handling for the owner pipelines. An owner may include an {@code email}: when present
11	 * it must be a syntactically valid address whose domain is not on the disposable-domain blocklist,
12	 * and is stored and returned lower-cased. When absent (null or blank) it is left unset. An invalid
13	 * or disposable address is rejected with {@link InvalidOwnerEmailException}.
14	 */
15	final class OwnerEmail {
16	
17	    /** WHATWG "valid email address" syntax — a widely accepted syntactic check. */
18	    private static final Pattern EMAIL = Pattern.compile(
19	            "^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+"
20	                    + "@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?"
21	                    + "(?:\\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$");
22	
23	    /** Known disposable email domains; an owner email in any of these is rejected. */
24	    private static final Set<String> DISPOSABLE_DOMAINS =
25	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
26	
27	    private OwnerEmail() {
28	    }
29	
30	    /**
31	     * Validates and normalizes the email on the request in place: a present, non-blank email is
32	     * trimmed, checked for syntax and lower-cased; a null or blank email is left unchanged.
33	     */
34	    static void normalize(OwnerFieldsDto request) throws InvalidOwnerEmailException {
35	        String email = request.getEmail();
36	        if (email == null || email.isBlank()) {
37	            return;
38	        }
39	        String trimmed = email.trim();
40	        if (!EMAIL.matcher(trimmed).matches()) {
41	            throw new InvalidOwnerEmailException(email);
42	        }
43	        String normalized = trimmed.toLowerCase();
44	        String domain = normalized.substring(normalized.indexOf('@') + 1);
45	        if (DISPOSABLE_DOMAINS.contains(domain)) {
46	            throw new InvalidOwnerEmailException(email);
47	        }
48	        request.setEmail(normalized);
49	    }
50	}
