1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerEmailException;
10	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerPostcodeException;
11	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerTelephoneException;
12	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
13	import org.springframework.web.bind.annotation.RequestBody;
14	
15	/**
16	 * Runs first in the create-owner pipeline. An owner must supply an address in EITHER form - a
17	 * non-blank {@code addressLine1} or the flat {@code address} - plus firstName, lastName, city and
18	 * telephone; a request missing or blank in any of these is rejected with
19	 * {@link MissingOwnerFieldsException} naming every offending field. Because {@link OwnerAddress}
20	 * normalizes and composes the address first, a supplied structured or flat address leaves a
21	 * non-blank composed {@code address}, so the single {@code address} check covers both forms.
22	 * Otherwise it publishes the body for later steps.
23	 */
24	public class ValidateOwnerFields {
25	
26	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
27	            throws MissingOwnerFieldsException, InvalidOwnerEmailException, InvalidOwnerTelephoneException,
28	            InvalidOwnerPostcodeException, FutureRegistrationDateException {
29	        // Normalize the address before the required-field check, so an address that is blank after
30	        // normalization is rejected and later steps see (and store) the canonical form.
31	        OwnerAddress.normalize(request);
32	        List<String> missing = new ArrayList<>();
33	        if (isBlank(request.getFirstName())) {
34	            missing.add("firstName");
35	        }
36	        if (isBlank(request.getLastName())) {
37	            missing.add("lastName");
38	        }
39	        if (isBlank(request.getAddress())) {
40	            missing.add("address");
41	        }
42	        if (isBlank(request.getCity())) {
43	            missing.add("city");
44	        }
45	        if (isBlank(request.getTelephone())) {
46	            missing.add("telephone");
47	        }
48	        if (!missing.isEmpty()) {
49	            throw new MissingOwnerFieldsException(missing);
50	        }
51	        // Store the telephone in E.164 form; reject a number that cannot form valid E.164.
52	        OwnerTelephone.normalize(request);
53	        // An owner may include an email; when present it must be valid and is stored lower-cased.
54	        OwnerEmail.normalize(request);
55	        // An owner may include a postcode; when present it must be 4 digits valid for the city's region.
56	        OwnerPostcode.validate(request);
57	        // An owner may supply a registrationDate; when present it must not be later than the server date.
58	        OwnerRegistrationDate.validate(request);
59	        validated.set(request);
60	    }
61	
62	    private static boolean isBlank(String value) {
63	        return value == null || value.isBlank();
64	    }
65	}
