9	/**
10	 * The household-duplicate block. The household is now keyed on the computed {@code householdId}
11	 * (last name + postcode), so a request that shares an existing owner's household is, by default, a
12	 * duplicate and is rejected with 409. Declaring {@code sharesHousehold: true} bypasses this block -
13	 * the owner is then created as a declared household member (and is not flagged as a suspected
14	 * duplicate later by {@link AssignPossibleDuplicate}).
15	 *
16	 * <p>Runs after {@link AssignHousehold} finalizes the id and before {@link CheckOwnerIdentityUnique}.
17	 * The two checks are distinct: this one is bypassed by {@code sharesHousehold}, whereas the identity
18	 * check (the full {@code telephone|email|householdId} key) never is - so a full duplicate that also
19	 * declares {@code sharesHousehold} still collides on its identity key.
20	 *
21	 * <p>The block is also bypassed when the new owner brings its own email: an email identifies a
22	 * genuinely distinct household member (the identity check still rejects a full duplicate that
23	 * repeats an existing telephone/email/household), so such an owner joins the household rather than
24	 * being rejected as a duplicate. An owner with no email that merely shares an existing household is
25	 * still treated as a duplicate and rejected.
26	 */
27	public class CheckOwnerHouseholdUnique {
28	
29	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository)
30	            throws HouseholdDuplicateException {
31	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
32	            return; // declared household member - bypass the duplicate block
33	        }
34	        String email = owner.getEmail();
35	        if (email != null && !email.isBlank()) {
36	            return; // brings its own email - a distinct household member, not a duplicate
37	        }
38	        String householdId = owner.getHouseholdId();
39	        for (Owner existing : ownerRepository.findAll()) {
40	            // The owner being created is not yet persisted, so findAll() returns only other owners.
41	            // A soft-deleted owner is ignored, so its household never blocks a new create.
42	            if (Boolean.TRUE.equals(existing.getDeleted())) {
43	                continue;
44	            }
45	            if (householdId.equals(existing.getHouseholdId())) {
46	                throw new HouseholdDuplicateException(householdId);
47	            }
48	        }
49	    }
50	}
